// StubRouter stands in for tool_call.ExecutionSignaler (Deps.Router, a
// forge:optional-dep). NewTestToolCall leaves the field nil, so a
// test that says nothing about it runs the code's nil path; a test of the
// other path passes one: WithToolCallDeps(Deps{Router: &StubRouter{...}}).
// It is the same shape as a forge contract mock:
// program a method by setting its <Method>Func field, and assert calls through
// the embedded contractkit.Recorder.
//
//	stub := &StubRouter{ /* <Method>Func: func(...) (...) { ... } */ }
//	svc := NewTestToolCall(t, WithToolCallDeps(Deps{Router: stub}))
//	// ...
//	stub.CallCount("<Method>")
//
// An UNPROGRAMMED method that returns an error returns
// testkit.StubNotConfigured, naming this stub and the method, with zero values
// beside it. It never answers nil: a nil error claims the call succeeded,
// which for a lookup means "found" (and the handler dereferences the nil it
// got) and for a policy check means ALLOW. A method with no error result
// returns its zero values.
type StubRouter struct {
	contractkit.Recorder
	SendToolExecutionCancelFunc     func(context.Context, string, string, string) error
	SendToolExecutionBackgroundFunc func(context.Context, string, string, string) error
}

func (s *StubRouter) SendToolExecutionCancel(a0 context.Context, a1 string, a2 string, a3 string) error {
	s.Recorder.Record("SendToolExecutionCancel", a0, a1, a2, a3)
	if s.SendToolExecutionCancelFunc != nil {
		return s.SendToolExecutionCancelFunc(a0, a1, a2, a3)
	}
	return testkit.StubNotConfigured("StubRouter", "SendToolExecutionCancel")
}

func (s *StubRouter) SendToolExecutionBackground(a0 context.Context, a1 string, a2 string, a3 string) error {
	s.Recorder.Record("SendToolExecutionBackground", a0, a1, a2, a3)
	if s.SendToolExecutionBackgroundFunc != nil {
		return s.SendToolExecutionBackgroundFunc(a0, a1, a2, a3)
	}
	return testkit.StubNotConfigured("StubRouter", "SendToolExecutionBackground")
}

// NewTestToolCallServer creates an httptest.Server with the ToolCall service registered.
// Returns the server and a typed Connect client.
//
// Access control is HANDLER LOGIC (GetUser + your own checks), not a
// generated interceptor, so the only thing standing in for production here
// is AUTHENTICATION: every call reaches the handler carrying the default test
// principal, installed server-side through middleware.ContextWithClaims.
// Server-side is the point — AuthedContext puts claims on a context the TEST
// holds, and a context does not cross HTTP, so passing it to a client call
// authenticates nothing. Adjust the principal with WithPrincipal, or drop it
// with WithoutPrincipal to assert an RPC refuses anonymous callers.
func NewTestToolCallServer(t *testing.T, opts ...TestOption) (*httptest.Server, reliantv1connect.ToolCallServiceClient) {
	t.Helper()
	cfg := testkit.ApplyOptions(defaultTestConfig(t), opts...)
	svc := newTestToolCallService(t, cfg)
	var handlerOpts []connect.HandlerOption
	if !cfg.anonymous {
		handlerOpts = append(handlerOpts, testkit.ServerPrincipal(middleware.ContextWithClaims, cfg.principal...))
	}
	return testkit.NewConnectClient(t, svc.Register, reliantv1connect.NewToolCallServiceClient, handlerOpts...)
}

func defaultTestConfig(t *testing.T) *testConfig {
	t.Helper()
	return &testConfig{
		logger: testkit.DiscardLogger(),
		cfg:    config.Defaults(),
	}
}

// AuthedContext returns a context carrying authenticated test claims,
// installed via middleware.ContextWithClaims — the same setter the
// production auth middleware uses — so handlers that call
// middleware.GetUser / middleware.ClaimsFromContext see a real principal.
//
// Defaults: UserID "test-user", Role/Roles "admin". Override with
// testkit.ClaimsOption values:
//
//	ctx := AuthedContext(t, testkit.WithRoles("viewer"))
func AuthedContext(t *testing.T, opts ...testkit.ClaimsOption) context.Context {
	return testkit.AuthedContext(t, middleware.ContextWithClaims, opts...)
}
